// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        bound(amount, 1, 1 ether);

        LogHelper log = new LogHelper();
        vm.prank(actor);
        c.SetLogFile(address(log));

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(0) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract LogHelper {
    function AddMessage(address, uint256, string memory) external pure {}
}
